/**
 * 浏览器集成测试从雾鸦板子炼金、渡鸦和村民的真实玩家档构造最小画面输入。
 * 两语跳转／倒看检查已授权事件、隐藏身份与胜者时点；只纳入玩家导出事件，不加入 God 私有知识。
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument, readReplayPlayerView } from "@ai-werewolf-arena/replay-contract";
import { createReplayRenderInput } from "../../src/replay/replay-frame";
import { eventLabel } from "../../src/replay/event-labels";
import { roleName } from "../../src/replay/replay-localization";
for (const actor of ["alchemist", "raven", "villager"] as const)
  for (const locale of ["en", "zh-CN"] as const)
    test(`Mist actual owner minimal movie input and rewind/${actor}/${locale}`, async ({
      page,
    }) => {
      const name = `mist-normal-linked-${locale}`;
      const god = readReplayDocument(
        JSON.parse(
          readFileSync(frontendFixtureURL(`frontend/tests/fixtures/${name}.replay.json`), "utf8"),
        ),
      );
      const view = readReplayPlayerView(
        JSON.parse(
          readFileSync(
            frontendFixtureURL(`frontend/tests/fixtures/player-views/${name}-${actor}.player.json`),
            "utf8",
          ),
        ),
      );
      const events = view.timeline.flatMap((row) =>
        row.kind === "event"
          ? [
              {
                seq: row.seq,
                timestamp: row.timestamp!,
                day: row.day,
                phase: row.phase,
                type: row.event.type,
                payload: row.event.payload,
              },
            ]
          : [],
      );
      // 用真实已授权归档构造最小渲染契约；这不是 UI 直接导入私有文件。
      const replay = readReplayDocument({
        ...god,
        result: { winner: null, reason: "private_render" },
        players: god.players.map((p) => ({
          ...p,
          role: p.player_id === view.player_id ? view.role : "unknown",
          camp: p.player_id === view.player_id ? view.camp : "unknown",
        })),
        events: events.map((e, i) => ({ ...e, seq: i + 1 })),
      });
      await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
      await page.goto("/");
      const input = createReplayRenderInput(replay, { locale, timeZone: "UTC" });
      const type =
        actor === "alchemist"
          ? "alchemist_snake_chosen"
          : actor === "raven"
            ? "raven_unsealed"
            : "night_resolved";
      const event = replay.events.find((e) => e.type === type && e.day === 2)!;
      const label = eventLabel(event, locale);
      await page.locator(".timeline .event").filter({ hasText: label }).first().click();
      await expect(page.getByTestId("composition-event")).toHaveText(label);
      for (const p of replay.players) {
        await expect(page.locator(`[data-composition-player="${p.player_id}"]`)).toContainText(
          roleName(p.player_id === view.player_id ? view.role : "unknown", locale),
        );
      }
      if (actor !== "alchemist")
        expect(replay.events.some((e) => e.type.startsWith("alchemist_"))).toBe(false);
      if (actor !== "raven")
        expect(replay.events.some((e) => e.type.startsWith("raven_"))).toBe(false);
      const index = input.replay.events.findIndex((e) => e.seq === event.seq);
      const slider = page.locator('.frame-control input[type="range"]');
      for (const frame of [index * 90 + 45, index * 90 - 1, 0]) {
        await slider.evaluate((el, value) => {
          Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")!.set!.call(
            el,
            String(value),
          );
          el.dispatchEvent(new Event("input", { bubbles: true }));
          el.dispatchEvent(new Event("change", { bubbles: true }));
        }, frame);
        await expect(slider).toHaveValue(String(frame));
        await expect(page.getByTestId("composition-event")).toHaveAttribute(
          "data-event-seq",
          String(input.replay.events[Math.floor(frame / 90)]!.seq),
        );
        await expect(page.getByTestId("composition-winner")).toHaveCount(0);
      }
      expect(await page.locator(".seat-grid .dead .seat-number").allTextContents()).toEqual([]);
    });

/**
 * 浏览器集成测试从光蚀各角色的真实玩家归档构造最小画面输入。
 * 两语跳转／倒看检查本人可见事件和身份遮蔽，预期保留原授权事件与未知身份，不引入 God 归档私有知识。
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument, readReplayPlayerView } from "@ai-werewolf-arena/replay-contract";
import { createReplayRenderInput } from "../../src/replay/replay-frame";
import { eventLabel } from "../../src/replay/event-labels";
import { roleName } from "../../src/replay/replay-localization";
for (const actor of ["maid", "count", "witch", "pack", "villager"] as const)
  for (const locale of ["en", "zh-CN"] as const)
    test(`Radiant actual owner minimal movie input and rewind/${actor}/${locale}`, async ({
      page,
    }) => {
      const name = `radiant-independent-stock-card16-card17-${locale}`;
      const god = readReplayDocument(
        JSON.parse(
          readFileSync(frontendFixtureURL(`frontend/tests/fixtures/${name}.replay.json`), "utf8"),
        ),
      );
      const view = readReplayPlayerView(
        JSON.parse(
          readFileSync(
            frontendFixtureURL(`frontend/tests/fixtures/player-views/${name}-${actor}.player.json`),
            "utf8",
          ),
        ),
      );
      const events = view.timeline.flatMap((row) =>
        row.kind === "event"
          ? [
              {
                seq: row.seq,
                timestamp: row.timestamp!,
                day: row.day,
                phase: row.phase,
                type: row.event.type,
                payload: row.event.payload,
              },
            ]
          : [],
      );
      // 用真实已授权归档构造最小渲染契约；这不是 UI 直接导入私有文件。
      const replay = readReplayDocument({
        ...god,
        result: { winner: null, reason: "private_render" },
        players: god.players.map((p) => ({
          ...p,
          role: p.player_id === view.player_id ? view.role : "unknown",
          camp: p.player_id === view.player_id ? view.camp : "unknown",
        })),
        events: events.map((e, i) => ({ ...e, seq: i + 1 })),
      });
      await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
      await page.goto("/");
      const input = createReplayRenderInput(replay, { locale, timeZone: "UTC" });
      const type =
        actor === "maid"
          ? "eclipse_swallowed"
          : actor === "count"
            ? "radiant_shelter_chosen"
            : actor === "witch"
              ? "eclipse_native_suppressed"
              : "night_resolved";
      const event = replay.events.find((e) => e.type === type && e.day === 2)!;
      const label = eventLabel(event, locale);
      await page.locator(".timeline .event").filter({ hasText: label }).first().click();
      await expect(page.getByTestId("composition-event")).toHaveText(label);
      for (const p of replay.players) {
        await expect(page.locator(`[data-composition-player="${p.player_id}"]`)).toContainText(
          roleName(p.player_id === view.player_id ? view.role : "unknown", locale),
        );
      }
      if (actor !== "maid")
        expect(replay.events.some((e) => e.type === "eclipse_swallowed")).toBe(false);
      expect(replay.events.some((e) => e.type === "eclipse_lease_closed")).toBe(false);
      const index = input.replay.events.findIndex((e) => e.seq === event.seq);
      const slider = page.locator('.frame-control input[type="range"]');
      for (const frame of [index * 90 + 45, index * 90 - 1, 0]) {
        await slider.evaluate((el, value) => {
          Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")!.set!.call(
            el,
            String(value),
          );
          el.dispatchEvent(new Event("input", { bubbles: true }));
          el.dispatchEvent(new Event("change", { bubbles: true }));
        }, frame);
        await expect(slider).toHaveValue(String(frame));
        await expect(page.getByTestId("composition-event")).toHaveAttribute(
          "data-event-seq",
          String(input.replay.events[Math.floor(frame / 90)]!.seq),
        );
        await expect(page.getByTestId("composition-winner")).toHaveCount(0);
      }
      expect(await page.locator(".seat-grid .dead .seat-number").allTextContents()).toEqual([]);
    });

/**
 * 浏览器集成测试验证赤月使徒到期、狼刀和自爆的两语归档。
 * 输入为原翻牌／死亡事实及 checkpoint；输出检查相应帧的公共字幕、席位和终局胜者，不在浏览器应用生命周期规则。
 */
import { frontendFixtureURL } from "../support/fixtures/manifest";
import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { readReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { text } from "@ai-werewolf-arena/game-text";
import { eventLabel } from "../../src/replay/event-labels";
for (const mode of ["expire", "knife", "blast"] as const)
  for (const locale of ["zh-CN", "en"] as const)
    test("Red Moon public reveal and death lifecycle " + mode + "/" + locale, async ({ page }) => {
      const base = "frontend/tests/fixtures/red-moon-" + mode + "-" + locale;
      const replay = readReplayDocument(
        JSON.parse(readFileSync(frontendFixtureURL(base + ".replay.json"), "utf8")),
      );
      const checkpoint = JSON.parse(
        readFileSync(frontendFixtureURL(base + ".checkpoint.txt"), "utf8"),
      ) as { players: Array<{ id: number; role: string; alive: boolean }> };
      const actor = checkpoint.players.find((p) => p.role === "red_moon_apostle")!.id;
      await page.route("**/api/replay", (route) => route.fulfill({ json: replay }));
      await page.goto("/");
      const seat = page.getByRole("button", {
        name:
          locale === "en" ? "Player " + actor + " · Seat " + actor : actor + "号 · Seat " + actor,
        exact: true,
      });
      for (const e of replay.events.filter((e) =>
        ["red_moon_night_sealed", "red_moon_exile_delayed", "red_moon_delay_expired"].includes(
          e.type,
        ),
      )) {
        const label = eventLabel(e, locale);
        await page.locator(".timeline .event").filter({ hasText: label }).first().click();
        await expect(page.getByTestId("composition-event")).toHaveText(label);
        if (e.type === "red_moon_exile_delayed") await expect(seat).not.toHaveClass(/dead/);
        else await expect(seat).toHaveClass(/dead/);
        if (e.type !== "red_moon_delay_expired")
          await expect(seat).toContainText(
            text(locale, "replay.role_revealed_badge", {
              role: locale === "zh-CN" ? "赤月使徒" : "Red Moon Apostle",
            }),
          );
      }
      await page.locator(".timeline .event").last().click();
      const dead = await page.locator(".seat-grid .dead .seat-number").allTextContents();
      expect(dead.map(Number)).toEqual(checkpoint.players.filter((p) => !p.alive).map((p) => p.id));
      await expect(page.getByTestId("composition-winner")).not.toHaveCount(0);
    });

/**
 * 单元组件测试验证丘比特关系与阵营胜者的归档展示。输入为四类固定归档及畸形关系事实；
 * 输出以手写胜者／存活数组检查终局、死亡与关系区分，并验证拒绝不留部分效果。帧／markup 为被测输出，不启动对局或模型。
 */
import { frontendFixtureURL } from "../../../support/fixtures/manifest";
import { text } from "@ai-werewolf-arena/game-text";
import { expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { renderToStaticMarkup } from "react-dom/server";
import { readReplayDocument, type ReplayEvent } from "@ai-werewolf-arena/replay-contract";
import { replayResultLabel } from "../../../../src/replay/replay-localization";
import { buildReplaySnapshot } from "../../../../src/replay/replay-projection";
import { createReplayRenderInput, buildReplayFrame } from "../../../../src/replay/replay-frame";
import { readReplayEvent } from "../../../../src/replay/replay-event-reader";
import { eventLabel } from "../../../../src/replay/event-labels";
import { ReplayFrame } from "../../../../src/replay/ReplayComposition";
const oracle = {
  mixed_netease: { winners: [1, 2, 3], alive: [1, 2, 3] },
  mixed_lui: { winners: [2, 3], alive: [2, 3] },
  root_hunter: { winners: [1, 2, 4, 5], alive: [4, 5] },
  dream_chain: { winners: [1, 2, 4, 5], alive: [5] },
};
for (const locale of ["zh-CN", "en"] as const)
  for (const kind of ["mixed_netease", "mixed_lui", "root_hunter", "dream_chain"] as const)
    test(`${locale}/${kind}: actual Cupid archive/studio/video show chain-final relation or faction winners separately from survival`, () => {
      const document = readReplayDocument(
          JSON.parse(
            readFileSync(
              frontendFixtureURL(`frontend/tests/fixtures/cupid-${kind}.replay.json`),
              "utf8",
            ),
          ),
        ),
        before = JSON.stringify(document),
        terminal = document.events.length - 1;
      const early = buildReplaySnapshot(document, terminal - 1),
        final = buildReplaySnapshot(document, terminal);
      expect(early.players.filter((p) => p.isWinner)).toEqual([]);
      expect(final.players.filter((p) => p.isWinner).map((p) => p.playerId)).toEqual(
        oracle[kind].winners,
      );
      expect(final.players.filter((p) => p.alive).map((p) => p.playerId)).toEqual(
        oracle[kind].alive,
      );
      const label = replayResultLabel(document, locale);
      if (kind.startsWith("mixed_")) {
        expect(label).toContain(locale === "en" ? "Cupid lovers" : "丘比特情侣组");
        expect(label).not.toContain("cupid_lovers");
      }
      for (const event of document.events.filter((e) =>
        [
          "cupid_lovers_chosen",
          "lover_recognized",
          "cupid_relation_resolved",
          "lovers_death",
        ].includes(e.type),
      )) {
        expect(readReplayEvent(event, [1, 2, 3, 4, 5])).not.toBeNull();
        expect(eventLabel(event, locale, [1, 2, 3, 4, 5])).not.toBe(text(locale, "replay.unknown"));
      }
      const input = createReplayRenderInput(document, { locale, timeZone: "UTC" }),
        frame = terminal * 90 + 15;
      expect(
        buildReplayFrame(input, frame)
          .snapshot.players.filter((p) => p.isWinner)
          .map((p) => p.playerId),
      ).toEqual(oracle[kind].winners);
      expect(renderToStaticMarkup(<ReplayFrame input={input} frame={frame} />)).toContain(
        locale === "en" ? "Cupid" : "丘比特",
      );
      expect(JSON.stringify(document)).toBe(before);
    });
test("Cupid known facts reject malformed/hidden-field envelopes without associations, partial labels or death effects", () => {
  const document = readReplayDocument(
    JSON.parse(
      readFileSync(
        frontendFixtureURL("frontend/tests/fixtures/cupid-mixed_netease.replay.json"),
        "utf8",
      ),
    ),
  );
  const base = document.events.find((event) => event.type === "lover_recognized")!;
  for (const payload of [
    { actorId: 2, partnerId: 3, pairCamps: ["good", "wolf"] },
    { actorId: 2, partnerId: 99 },
    { actorId: 2, partnerId: 2 },
  ])
    expect(readReplayEvent({ ...base, payload }, [1, 2, 3, 4, 5])).toBeNull();
  const choice = document.events.find((event) => event.type === "cupid_lovers_chosen")!;
  expect(
    readReplayEvent(
      { ...choice, payload: { actorId: 1, day: 1, pairIds: [2, 3, 5] } },
      [1, 2, 3, 4, 5],
    ),
  ).toBeNull();
  const relation = document.events.find((event) => event.type === "cupid_relation_resolved")!;
  expect(
    readReplayEvent(
      { ...relation, payload: { ...relation.payload, mixed: false } },
      [1, 2, 3, 4, 5],
    ),
  ).toBeNull();
  const death =
    document.events.find((event) => event.type === "lovers_death") ??
    ({ ...base, type: "lovers_death", payload: { actorId: 2, targetId: 3 } } as ReplayEvent);
  expect(readReplayEvent(death, [1, 2, 3, 4, 5])!.effects).toEqual([
    { kind: "deaths", playerIds: [3] },
  ]);
});

/**
 * 单元组件测试用手写放逐／反馈复盘核对守墓人两语展示。输入为三种阵营标签和畸形反馈；
 * 输出以字面死亡席位／字幕检查被动知识不杀人、严格拒绝与纯帧／markup，保原数据不变，不执行真实放逐。
 */
import { expect, test } from "bun:test";
import { renderToStaticMarkup } from "react-dom/server";
import { readReplayDocument, readGravekeeperFeedback } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "../../../../src/replay/event-labels";
import { buildReplaySnapshot } from "../../../../src/replay/replay-projection";
import { createReplayRenderInput, buildReplayFrame } from "../../../../src/replay/replay-frame";
import { ReplayFrame } from "../../../../src/replay/ReplayComposition";
for (const locale of ["zh-CN", "en"] as const)
  for (const camp of ["good", "wolf", "third_party"] as const)
    test(`${locale}/${camp}: passive feedback changes no life, renders only the exact camp and keeps raw data and pure frames`, () => {
      const raw = {
        schemaVersion: 2,
        sessionId: "grave-display",
        perspective: "god",
        meta: {
          board: "grave_demo",
          locale,
          startedAt: "2026-10-08T00:00:00.000Z",
          endedAt: "2026-10-08T00:01:00.000Z",
        },
        result: { winner: null, reason: "in_progress" },
        players: [
          { player_id: 1, role: "wolf", camp: "wolf" },
          { player_id: 2, role: "gravekeeper", camp: "good" },
          { player_id: 3, role: "villager", camp: "good" },
        ],
        events: [
          {
            seq: 1,
            day: 1,
            phase: "voting",
            timestamp: "2026-10-08T00:00:00.000Z",
            type: "voted_out",
            payload: { target: 1 },
          },
          {
            seq: 2,
            day: 2,
            phase: "night",
            stage: "gravekeeper_feedback",
            timestamp: "2026-10-08T00:01:00.000Z",
            type: "gravekeeper_reported",
            payload: {
              actorId: 2,
              targetId: 1,
              exileDay: 1,
              receivedDay: 2,
              result: { kind: "camp", camp },
            },
          },
        ],
      };
      const before = structuredClone(raw),
        replay = readReplayDocument(raw),
        snapshot = buildReplaySnapshot(replay, 1);
      expect(
        snapshot.players.filter((player) => !player.alive).map((player) => player.playerId),
      ).toEqual([1]);
      const label =
        camp === "good"
          ? locale === "en"
            ? "Good"
            : "好人"
          : camp === "wolf"
            ? locale === "en"
              ? "Werewolves"
              : "狼人"
            : locale === "en"
              ? "Third party"
              : "第三方";
      const expected =
        locale === "en"
          ? `Gravekeeper 2 learns on night 2 that player 1, exiled on day 1, has camp label ${label}`
          : `2号守墓人在第2夜获知第1日放逐1号的阵营标签：${label}`;
      expect(eventLabel(replay.events[1], locale)).toBe(expected);
      const input = createReplayRenderInput(replay, { locale, timeZone: "UTC" });
      expect(buildReplayFrame(input, 100).label).toBe(expected);
      const markup = renderToStaticMarkup(<ReplayFrame input={input} frame={100} />);
      expect(markup).toContain(expected);
      expect(markup).toBe(renderToStaticMarkup(<ReplayFrame input={input} frame={100} />));
      expect(raw).toEqual(before);
      const valid = replay.events[1].payload;
      for (const payload of [
        { ...valid, result: { kind: "role", role: "wolf_king" } },
        { ...valid, result: { kind: "camp", camp: "unknown" } },
        { ...valid, targetId: 0 },
        { ...valid, receivedDay: 3 },
        { ...valid, extra: "untrusted" },
      ]) {
        expect(readGravekeeperFeedback(payload)).toBeNull();
        expect(eventLabel({ ...replay.events[1], payload }, locale)).toBe(
          locale === "en" ? "Unknown" : "未知",
        );
      }
    });

/**
 * 单元组件测试将原归档猎人枪事件替为中性 player_shot。输入保原目标和两语帧号；
 * 输出对照旧死亡投影并以字面字幕核对不宣称枪主身份，另核静态 markup 和旧归档未改，不执行死亡 hook。
 */
import { expect, test } from "bun:test";
import { renderToStaticMarkup } from "react-dom/server";
import { readReplayDocument } from "@ai-werewolf-arena/replay-contract";
import { eventLabel } from "../../../../src/replay/event-labels";
import { buildReplaySnapshot } from "../../../../src/replay/replay-projection";
import {
  createReplayRenderInput,
  buildReplayFrame,
  FRAMES_PER_EVENT,
} from "../../../../src/replay/replay-frame";
import { ReplayFrame } from "../../../../src/replay/ReplayComposition";
import twelve from "../../../fixtures/twelve-player-mirror-twelve/mirror-twelve/en/god.replay.json";

for (const locale of ["zh-CN", "en"] as const)
  test(`${locale}: a neutral shot preserves legacy God seats and renders without a gun-owner role label`, () => {
    const old = readReplayDocument(twelve),
      oldIndex = old.events.findIndex((e) => e.type === "hunter_shot");
    expect(oldIndex).toBeGreaterThan(0);
    const raw = structuredClone(twelve);
    const shot = raw.events[oldIndex];
    const before = structuredClone(shot);
    shot.type = "player_shot";
    shot.stage = "death_shot";
    shot.payload = { actorId: 7, targetId: 2 } as typeof shot.payload;
    const replay = readReplayDocument(raw),
      event = replay.events[oldIndex];
    expect(
      buildReplaySnapshot(replay, oldIndex - 1).players.find((p) => p.playerId === 2)!.alive,
    ).toBe(true);
    expect(buildReplaySnapshot(replay, oldIndex).players).toEqual(
      buildReplaySnapshot(old, oldIndex).players,
    );
    expect(buildReplaySnapshot(replay, oldIndex).players.find((p) => p.playerId === 2)!.alive).toBe(
      false,
    );
    const label = locale === "en" ? "Player 7 shoots player 2" : "7号开枪带走2号";
    expect(eventLabel(event, locale)).toBe(label);
    const input = createReplayRenderInput(replay, { locale, timeZone: "UTC" });
    const frame = input.replay.events.findIndex((e) => e.seq === event.seq) * FRAMES_PER_EVENT + 10;
    expect(buildReplayFrame(input, frame).label).toBe(label);
    expect(renderToStaticMarkup(<ReplayFrame input={input} frame={frame} />)).toContain(label);
    expect(old.events[oldIndex]).toMatchObject(before);
    expect(eventLabel(old.events[oldIndex], locale)).toBe(
      locale === "en" ? "Hunter 7 shoots player 2" : "7号猎人开枪带走2号",
    );
  });
